import json, os, sys, copy
D = sys.argv[1]
def base(**kw):
    c = {"schema_version": 1, "resolution_ms": 0.1, "seed": 1,
         "populations": [{"id": "A", "model": "iaf_psc_alpha", "n": 2}, {"id": "B", "model": "iaf_psc_alpha", "n": 2}],
         "projections": [{"pre": "A", "post": "B", "rule": "all_to_all", "synapse": {"weight": 500.0, "delay": 1.0}}],
         "inputs": [{"name": "s", "kind": "dc", "targets": ["A"], "value": 500.0}],
         "outputs": [{"name": "m", "neurons": ["B"]}]}
    c.update(kw); return c
cases = {}
def P(name, c): cases[name] = c if isinstance(c, str) else json.dumps(c)
P("ok", base())
P("n_1e7", base(populations=[{"id": "A", "model": "iaf_psc_alpha", "n": 10000000}, {"id": "B", "model": "iaf_psc_alpha", "n": 2}]))
