P("a2a_1e4_self", base(populations=[{"id": "A", "model": "iaf_psc_alpha", "n": 20000}, {"id": "B", "model": "iaf_psc_alpha", "n": 2}], projections=[{"pre": "A", "post": "A", "rule": "all_to_all", "synapse": {"weight": 1.0}}]))
P("fixed_total_1e9", base(projections=[{"pre": "A", "post": "B", "rule": "fixed_total_number", "N": 1000000000, "synapse": {"weight": 1.0}}]))
