P("taum_neg", base(populations=[{"id": "A", "model": "iaf_psc_alpha", "n": 2, "params": {"tau_m": -1.0}}, {"id": "B", "model": "iaf_psc_alpha", "n": 2}]))
P("param_string", base(populations=[{"id": "A", "model": "iaf_psc_alpha", "n": 2, "params": {"tau_m": "abc"}}, {"id": "B", "model": "iaf_psc_alpha", "n": 2}]))
P("param_unknown", base(populations=[{"id": "A", "model": "iaf_psc_alpha", "n": 2, "params": {"zzz": 1.0}}, {"id": "B", "model": "iaf_psc_alpha", "n": 2}]))
P("param_nested", base(populations=[{"id": "A", "model": "iaf_psc_alpha", "n": 2, "params": {"V_m": {"a": [1, 2]}}}, {"id": "B", "model": "iaf_psc_alpha", "n": 2}]))
P("param_array", base(populations=[{"id": "A", "model": "iaf_psc_alpha", "n": 2, "params": {"V_m": [1.0, 2.0, 3.0]}}, {"id": "B", "model": "iaf_psc_alpha", "n": 2}]))
P("model_unknown", base(populations=[{"id": "A", "model": "nope", "n": 2}, {"id": "B", "model": "iaf_psc_alpha", "n": 2}]))
for dev in ["spike_recorder", "poisson_generator", "dc_generator", "multimeter", "volume_transmitter", "spike_generator", "parrot_neuron", "weight_recorder", "step_current_generator", "noise_generator", "gif_pop_psc_exp", "pp_pop_psc_delta", "music_event_out_proxy", "correlation_detector", "spin_detector", "ht_neuron", "iaf_cond_alpha_mc", "sinusoidal_gamma_generator", "inhomogeneous_poisson_generator", "spike_dilutor", "mip_generator", "pulsepacket_generator", "gamma_sup_generator", "ppd_sup_generator", "erfc_neuron", "ginzburg_neuron", "mcculloch_pitts_neuron", "siegert_neuron", "lin_rate_ipn", "rate_transformer_lin", "aeif_cond_alpha_multisynapse", "iaf_psc_exp_multisynapse", "glif_psc", "glif_cond"]:
    P("pop_" + dev, base(populations=[{"id": "A", "model": "iaf_psc_alpha", "n": 2}, {"id": "B", "model": dev, "n": 2}], inputs=[{"name": "s", "kind": "dc", "targets": ["A"], "value": 500.0}], outputs=[{"name": "m", "neurons": ["A"]}]))
    P("popsrc_" + dev, base(populations=[{"id": "A", "model": dev, "n": 2}, {"id": "B", "model": "iaf_psc_alpha", "n": 2}], inputs=[], outputs=[{"name": "m", "neurons": ["B"]}]))
