P("deep_nest_params", "{\"schema_version\":1,\"populations\":[{\"id\":\"A\",\"model\":\"iaf_psc_alpha\",\"n\":1,\"params\":{\"x\":" + "{\"a\":" * 50000 + "1" + "}" * 50000 + "}}]}")
P("n_float", base(populations=[{"id": "A", "model": "iaf_psc_alpha", "n": 2.5}, {"id": "B", "model": "iaf_psc_alpha", "n": 2}]))
