P("rate_inf_loop", base(populations=[{"id": "A", "model": "lin_rate_ipn", "n": 2}], projections=[{"pre": "A", "post": "A", "rule": "all_to_all", "synapse": {"synapse_model": "rate_connection_instantaneous", "weight": 10.0}}], inputs=[{"name": "s", "kind": "rate_drive", "targets": ["A"], "value": 1.0}], outputs=[{"name": "m", "kind": "rate_value", "neurons": ["A"]}]))
P("res_min", base(resolution_ms=0.001))
